std::mutex m;  std::condition_variable cv;  std::deque<Item> q;
Item take() {
    std::unique_lock lk{m};
    cv.wait(lk, [] { return !q.empty(); });   // while(!pred) wait(lk)
    Item it = std::move(q.front()); q.pop_front();
    return it;                                // lock released by ~lk
}

void put(Item it) {
    { std::lock_guard lk{m}; q.push_back(std::move(it)); }  // state first
    cv.notify_one();                                        // then signal
}

