std::atomic<int> seq{0};

void producer(Payload *p) {
    publish(p);                                  // publish, then bump
    seq.fetch_add(1, std::memory_order_release);
    seq.notify_one();
}
void consumer() {
    int seen = 0;
    while (!(seen = seq.load(std::memory_order_acquire)))
        seq.wait(seen, std::memory_order_acquire);   // returns only on change
}
